package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.text.Layout;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
/** Disposable emulator audit: actual layouts at 130%, not product-time listeners. */
@androidx.media3.common.util.UnstableApi
public class ScreenLayoutReviewTest {
 private final Instrumentation ins=getInstrumentation();
 private String shell(String command)throws Exception{try(InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(ins.getUiAutomation().executeShellCommand(command));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8").trim();}}
 private ScrollView scroll(View view){if(view instanceof ScrollView)return (ScrollView)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){ScrollView found=scroll(((ViewGroup)view).getChildAt(i));if(found!=null)return found;}return null;}
 private void inspect(Activity screen,View view,List<String> problems){if(view instanceof TextView&&view.isShown()){TextView text=(TextView)view;Rect visible=new Rect();Layout layout=text.getLayout();if(layout!=null&&text.getText().length()>0&&text.getGlobalVisibleRect(visible)&&visible.height()>=text.getHeight()-2){int space=text.getHeight()-text.getCompoundPaddingTop()-text.getCompoundPaddingBottom();if(space+3<layout.getHeight())problems.add(screen.getClass().getSimpleName()+": "+text.getText().toString().replace('\n',' ').substring(0,Math.min(70,text.getText().length()))+" text="+layout.getHeight()+" available="+space);}}
  if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)inspect(screen,((ViewGroup)view).getChildAt(i),problems);
 }
 @Test public void primaryScreensHaveReadableControlsAndScrollableFormsAtLargeFont()throws Exception{
  Context c=ins.getTargetContext();assertTrue("Only run on an emulator",shell("getprop ro.kernel.qemu").equals("1")||shell("getprop ro.boot.qemu").equals("1"));String oldFont=shell("settings get system font_scale");SharedPreferences radio=c.getSharedPreferences("radio",0);String[] keys={"catalog","query","city","catalog_city"};Map<String,String> old=new HashMap<>();for(String key:keys)old.put(key,radio.getString(key,null));boolean hadCountry=radio.contains("brazil"),country=radio.getBoolean("brazil",true);List<String> problems=new ArrayList<>();JSONArray screens=new JSONArray();Activity current=null;
  Class<?>[] pages={MainActivity.class,OnlineActivity.class,DownloadsActivity.class,DownloadCenterActivity.class,LocalConverterActivity.class,OndaFilesActivity.class,ImageSearchActivity.class,RadioActivity.class,YouTubeActivity.class,YouTubeFavoritesActivity.class,VideoActivity.class,PdfActivity.class,AppearanceActivity.class,AudioOutputActivity.class,SoundActivity.class,SpeechActivity.class,AudioChaptersActivity.class,BackupActivity.class,UpdateActivity.class,VoicePhrasesActivity.class,QueueActivity.class,PlaylistsActivity.class,SmartLibraryActivity.class,DjActivity.class,ShelfActivity.class,UnifiedSearchActivity.class,LyricsActivity.class,ConnectActivity.class};
  try{RadioStation fixture=new RadioStation("layout-audit","Rádio de layout","https://radio.example.org/layout","Brasil","AAC",128,false);RadioStore.cache(c,Collections.singletonList(fixture),"",true);radio.edit().remove("city").putString("catalog_city","").commit();shell("settings put system font_scale 1.3");Thread.sleep(700);
   for(Class<?> type:pages){current=ins.startActivitySync(new Intent(c,type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity screen=current;ins.waitForIdleSync();Thread.sleep(180);ins.runOnMainSync(()->{assertFalse(type.getSimpleName()+" unexpectedly closed",screen.isFinishing());assertEquals(1.3f,screen.getResources().getConfiguration().fontScale,.02f);View root=screen.findViewById(android.R.id.content);assertTrue(type.getSimpleName()+" empty layout",root.getWidth()>0&&root.getHeight()>0);inspect(screen,root,problems);ScrollView form=scroll(root);if(type==UpdateActivity.class)assertNotNull("Updates must scroll at large font",form);if(form!=null){form.setSmoothScrollingEnabled(false);form.fullScroll(View.FOCUS_DOWN);}});ins.waitForIdleSync();Thread.sleep(60);ins.runOnMainSync(()->inspect(screen,screen.findViewById(android.R.id.content),problems));screens.put(type.getSimpleName());ins.runOnMainSync(screen::finish);ins.waitForIdleSync();current=null;}
   JSONObject report=new JSONObject().put("fontScale",1.3).put("screens",screens).put("screenCount",screens.length()).put("clippedNativeText",new JSONArray(problems)).put("updatesFormScrolls",true).put("noProductPollingAdded",true);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"screen-layout-review.json"))){out.write(report.toString(2).getBytes("UTF-8"));}assertTrue("Clipped native text: "+problems,problems.isEmpty());
  }finally{if(current!=null){Activity screen=current;ins.runOnMainSync(screen::finish);}shell(oldFont.equals("null")?"settings delete system font_scale":"settings put system font_scale "+oldFont);Thread.sleep(500);SharedPreferences.Editor edit=radio.edit();for(String key:keys)if(old.get(key)==null)edit.remove(key);else edit.putString(key,old.get(key));if(hadCountry)edit.putBoolean("brazil",country);else edit.remove("brazil");edit.commit();}
 }
}
